sc_cat_item_producer.script:
/** This script is executed before the Record is generated
* `current`- GlideRecord produced by Record Producer
* Don't use `current.update()` or `current.insert()` as the record is generated by Record Producer
* Don't use `current.setValue('sys_class_name', 'xxx')` as this will trigger reparent flow and can cause data loss
* Avoid `current.setAbortAction()` and generate a separate record
* Use `producer.var1` to access variables
*/

(function () {

    var notOnFile = producer.not_on_file.toString();
    if (notOnFile == 'true' || notOnFile == 'Yes') {
        var plate = producer.visitor_plate.toString().toUpperCase().replace(/ /g, '');
        var province = producer.visitor_state.toString();

        var newVehicle = new GlideRecord('x_1234_parking_c_0_vehicle');
        newVehicle.addQuery('plate', plate);
        newVehicle.addQuery('plate_state', province);
        newVehicle.query();

        if (newVehicle.next()) {
            current.vehicle = newVehicle.sys_id;
        } else {
            newVehicle.initialize();
            newVehicle.plate = plate;
            newVehicle.plate_state = province;
            newVehicle.make = producer.visitor_make.toString();
            newVehicle.model = producer.visitor_model.toString();
            newVehicle.color = producer.visitor_color.toString();
            var newId = newVehicle.insert();
            gs.info('[Parking] vehicle insert returned: ' + newId);
            current.vehicle = newId;
        }
        current.cited_person_type = 'guest';
    }

})();
